from pathlib import Path
from typing import List

def plan_archive(root: str, names: List[str]) -> List[Path]:
    root_path = Path(root)

    # Reject empty or root aliases
    if not root_path or root_path.is_absolute():
        raise ValueError("Empty or root aliases are not allowed")

    # Reject POSIX absolute or parent paths
    if root_path.is_absolute():
        raise ValueError("POSIX absolute paths are not allowed")

    # Reject Windows drive or backslash traversal
    if root_path.parts[0].startswith(('\\', 'C:', 'D:', 'E:')):
        raise ValueError("Windows drive or backslash traversal is not allowed")

    # Reject existing symlink escapes
    if root_path.is_symlink():
        raise ValueError("Existing symlinks are not allowed")

    # Resolve each name and check for duplicates
    resolved_paths = []
    seen_destinations = set()

    for name in names:
        path = root_path / name
        if path.is_symlink():
            raise ValueError("Existing symlinks are not allowed")

        # Resolve path to canonical form
        try:
            canonical = path.resolve()
        except OSError:
            raise ValueError(f"Cannot resolve path: {name}")

        # Check for duplicate destinations
        if canonical in seen_destinations:
            raise ValueError(f"Two spellings resolve to the same destination: {name}")

        seen_destinations.add(canonical)
        resolved_paths.append(canonical)

    # Reject if any path is a parent path (e.g., ..)
    for p in resolved_paths:
        if p.parts[-1] == '..':
            raise ValueError("Parent paths are not allowed")

    return resolved_paths
