import os
from pathlib import Path, PurePosixPath, PureWindowsPath

def plan_archive(root, names):
    base = Path(root).resolve()
    planned = []
    seen = set()
    for name in names:
        raw = os.fspath(name)
        if not raw or raw == '.':
            raise ValueError("empty or root alias")
        if isinstance(raw, str):
            path = PurePosixPath(raw.replace('\\', '/'))
            if path.is_absolute() or '..' in path.parts:
                raise ValueError("absolute or parent path")
            if any(part == '..' for part in path.parts):
                raise ValueError("parent path traversal")
            windows = PureWindowsPath(raw)
            if windows.drive or windows.root:
                raise ValueError("Windows drive or backslash traversal")
            key = tuple(path.parts)
            if key in seen:
                raise ValueError("duplicate resolved destination")
            seen.add(key)
            candidate = base.joinpath(*path.parts).resolve()
            if candidate == base or not candidate.is_relative_to(base):
                raise ValueError("escape from root directory")
            planned.append(candidate)
        else:
            raise ValueError("invalid member type")
    return planned
