                    raise ValueError(f"Symlink collision at {path}")
                seen_symlinks.add(path.resolve())
            # If path exists and is a file/directory, check for name collision
            if path.exists():
                if path.name in seen_names:
                    raise ValueError(f"Name collision: {path.name}")
                seen_names.add(path.name)
        except Exception as e:
            raise ValueError(f"Path resolution error: {e}")

