def quarantine_move(sources: List[Path], quarantine_dir: Path) -> List[Path]:
    # Validate that quarantine_dir exists and is a directory
    if not quarantine_dir.exists():
        raise FileNotFoundError(f"Quarantine directory does not exist: {quarantine_dir}")
    if not quarantine_dir.is_dir():
        raise NotADirectoryError(f"Quarantine path is not a directory: {quarantine_dir}")

    # Validate that every source exists and is a file
    target_paths = []
    for source in sources:
        if not source.exists():
            raise FileNotFoundError(f"Source does not exist: {source}")
        if not source.is_file():
            raise ValueError(f"Source is not a file: {source}")

    # Check if any target already exists in quarantine_dir
    for source in sources:
        target_path = quarantine_dir / source.name
        if target_path.exists():
            raise FileExistsError(f"Target already exists in quarantine directory: {target_path}")

    # Move files, one by one
    moved_files = []
    for source in sources:
        target_path = quarantine_dir / source.name
        try:
            source.rename(target_path)
            moved_files.append(target_path)
        except Exception as e:
            # If move fails, rollback all previous moves
            for moved in moved_files:
                try:
                    moved.unlink(moved)
                except Exception:
                    pass  # Ignore errors during rollback
            raise e

    return moved_files
