import os
from pathlib import Path
from typing import List

def quarantine_move(sources: List[Path], quarantine_dir: Path) -> List[Path]:
    """Move sources to quarantine_dir, validating existence and absence of targets before moving."""
    if not quarantine_dir.exists():
        quarantine_dir.mkdir(parents=True, exist_ok=True)

    targets = []
    for src in sources:
        if not src.exists():
            raise FileNotFoundError(f"source does not exist: {src}")
        target_path = quarantine_dir / src.name
        if target_path.exists():
            raise FileExistsError(f"target already exists: {target_path}")

        try:
            # Move the file/directory
            src.rename(target_path)
            targets.append(target_path)
        except OSError as e:
            # If move fails, rollback all previous moves
            for t in targets:
                try:
                    t.unlink(missing_ok=True)
                except OSError:
                    pass
            raise e

    return targets
